-- Authoritative historical profit facts shared by Profit Report and Dashboard.
CREATE OR REPLACE FUNCTION public.profit_report_item_rows(p_filters jsonb DEFAULT '{}'::jsonb)
RETURNS TABLE(sale_item_id uuid,sale_id uuid,invoice_number text,sale_date timestamptz,customer_name text,cashier_id uuid,cashier_name text,payment_method text,status text,product_id uuid,product_name text,article text,category_id uuid,category_name text,brand_id uuid,brand_name text,variant_id uuid,size text,colour text,barcode text,quantity integer,returned_quantity integer,net_quantity integer,selling_price numeric,gross_sales numeric,item_discount numeric,invoice_discount numeric,discount numeric,returned_value numeric,net_revenue numeric,unit_cost numeric,sold_cogs numeric,reversed_cogs numeric,cogs numeric,profit numeric,margin numeric)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
WITH bounds AS(SELECT CASE WHEN coalesce(p_filters->>'startDate','')='' THEN '-infinity'::timestamptz ELSE (p_filters->>'startDate')::date::timestamp AT TIME ZONE 'Asia/Colombo' END d1,CASE WHEN coalesce(p_filters->>'endDate','')='' THEN 'infinity'::timestamptz ELSE ((p_filters->>'endDate')::date+1)::timestamp AT TIME ZONE 'Asia/Colombo' END d2),
returns AS(SELECT sri.sale_item_id,sum(sri.quantity_returned)::int returned_quantity,sum(sri.return_total) returned_value,sum(CASE WHEN sri.restock_item THEN sri.quantity_returned*coalesce(sri.cost_price_at_sale,si.cost_price_at_sale,si.cost_price) ELSE 0 END) reversed_cogs FROM public.sales_return_items sri JOIN public.sales_returns sr ON sr.id=sri.return_id AND sr.status='completed' JOIN public.sale_items si ON si.id=sri.sale_item_id GROUP BY sri.sale_item_id),
raw AS(SELECT si.id sale_item_id,si.sale_id,s.invoice_number,s.created_at sale_date,coalesce(c.name,'Walk-in Customer') customer_name,s.user_id cashier_id,coalesce(pr.full_name,pr.email,'Unknown') cashier_name,coalesce(s.payment_method,'') payment_method,s.status,p.id product_id,coalesce(p.name,si.product_name,si.product_name_snapshot,'Unknown Product') product_name,p.item_article article,p.category_id,coalesce(ca.name,'Uncategorized') category_name,p.brand_id,coalesce(b.name,'Unbranded') brand_name,si.variant_id,coalesce(si.size_snapshot,pv.size) size,coalesce(si.color_snapshot,pv.color) colour,coalesce(si.barcode_number_snapshot,pv.barcode_number) barcode,si.quantity::int quantity,least(coalesce(r.returned_quantity,0),si.quantity)::int returned_quantity,si.selling_price,coalesce(si.line_subtotal,si.selling_price*si.quantity) gross_sales,coalesce(si.discount_amount,0) item_discount,coalesce(s.invoice_discount_amount,0) invoice_discount_total,greatest(coalesce(si.line_subtotal,si.selling_price*si.quantity)-coalesce(si.discount_amount,0),0) discount_basis,sum(greatest(coalesce(si.line_subtotal,si.selling_price*si.quantity)-coalesce(si.discount_amount,0),0))OVER(PARTITION BY si.sale_id) invoice_basis,coalesce(r.returned_value,0) returned_value,coalesce(si.cost_price_at_sale,si.cost_price) unit_cost,coalesce(r.reversed_cogs,0) reversed_cogs
FROM public.sale_items si JOIN public.sales s ON s.id=si.sale_id CROSS JOIN bounds x LEFT JOIN public.customers c ON c.id=s.customer_id LEFT JOIN public.profiles pr ON pr.id=s.user_id LEFT JOIN public.product_variants pv ON pv.id=si.variant_id LEFT JOIN public.products p ON p.id=pv.product_id LEFT JOIN public.categories ca ON ca.id=p.category_id LEFT JOIN public.brands b ON b.id=p.brand_id LEFT JOIN returns r ON r.sale_item_id=si.id
WHERE s.created_at>=x.d1 AND s.created_at<x.d2 AND s.status IN('completed','partially_returned','fully_returned') AND (coalesce(p_filters->>'categoryId','')='' OR p.category_id=(p_filters->>'categoryId')::uuid) AND(coalesce(p_filters->>'brandId','')='' OR p.brand_id=(p_filters->>'brandId')::uuid) AND(coalesce(p_filters->>'productId','')='' OR p.id=(p_filters->>'productId')::uuid) AND(coalesce(p_filters->>'paymentMethod','')='' OR s.payment_method=p_filters->>'paymentMethod') AND(coalesce(p_filters->>'cashierId','')='' OR s.user_id=(p_filters->>'cashierId')::uuid) AND(coalesce(p_filters->>'search','')='' OR s.invoice_number ILIKE '%'||(p_filters->>'search')||'%' OR coalesce(c.name,'') ILIKE '%'||(p_filters->>'search')||'%' OR coalesce(pr.full_name,pr.email,'') ILIKE '%'||(p_filters->>'search')||'%' OR coalesce(p.name,si.product_name,si.product_name_snapshot,'') ILIKE '%'||(p_filters->>'search')||'%' OR coalesce(p.item_article,'') ILIKE '%'||(p_filters->>'search')||'%' OR coalesce(si.barcode_number_snapshot,pv.barcode_number,'') ILIKE '%'||(p_filters->>'search')||'%')),
priced AS(SELECT r.*,CASE WHEN invoice_basis>0 THEN invoice_discount_total*discount_basis/invoice_basis ELSE 0 END invoice_discount FROM raw r)
SELECT sale_item_id,sale_id,invoice_number,sale_date,customer_name,cashier_id,cashier_name,payment_method,status,product_id,product_name,article,category_id,category_name,brand_id,brand_name,variant_id,size,colour,barcode,quantity,returned_quantity,quantity-returned_quantity net_quantity,selling_price,gross_sales,item_discount,invoice_discount,item_discount+invoice_discount discount,returned_value,gross_sales-item_discount-invoice_discount-returned_value net_revenue,unit_cost,CASE WHEN unit_cost IS NULL THEN NULL ELSE unit_cost*quantity END sold_cogs,reversed_cogs,CASE WHEN unit_cost IS NULL THEN NULL ELSE unit_cost*quantity-reversed_cogs END cogs,CASE WHEN unit_cost IS NULL THEN NULL ELSE gross_sales-item_discount-invoice_discount-returned_value-(unit_cost*quantity-reversed_cogs) END profit,CASE WHEN gross_sales-item_discount-invoice_discount-returned_value=0 OR unit_cost IS NULL THEN 0 ELSE (gross_sales-item_discount-invoice_discount-returned_value-(unit_cost*quantity-reversed_cogs))/(gross_sales-item_discount-invoice_discount-returned_value)*100 END margin FROM priced;
$$;

CREATE OR REPLACE FUNCTION public.get_profit_report(p_filters jsonb DEFAULT '{}'::jsonb,p_page integer DEFAULT 1,p_page_size integer DEFAULT 25,p_sort text DEFAULT 'newest') RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$
WITH items AS(SELECT * FROM public.profit_report_item_rows(p_filters)),invoices0 AS(SELECT sale_id,max(invoice_number)invoice_number,max(sale_date)sale_date,max(customer_name)customer_name,max(cashier_name)cashier_name,count(*)::int item_count,sum(net_quantity)::int quantity,sum(gross_sales)gross_sales,sum(discount)discount,sum(net_revenue)net_sales,CASE WHEN bool_or(cogs IS NULL)THEN NULL ELSE sum(cogs)END cogs,CASE WHEN bool_or(profit IS NULL)THEN NULL ELSE sum(profit)END profit,max(payment_method)payment_method,max(status)status FROM items GROUP BY sale_id),invoices AS(SELECT *,CASE WHEN net_sales=0 OR profit IS NULL THEN 0 ELSE profit/net_sales*100 END margin FROM invoices0 WHERE coalesce(p_filters->>'profitStatus','')='' OR(p_filters->>'profitStatus'='profit' AND profit>=0)OR(p_filters->>'profitStatus'='loss' AND profit<0)),summary AS(SELECT coalesce(sum(net_sales),0)net_revenue,CASE WHEN bool_or(cogs IS NULL)THEN NULL ELSE coalesce(sum(cogs),0)END cogs,CASE WHEN bool_or(profit IS NULL)THEN NULL ELSE coalesce(sum(profit),0)END gross_profit,CASE WHEN sum(net_sales)=0 OR bool_or(profit IS NULL)THEN 0 ELSE sum(profit)/sum(net_sales)*100 END profit_margin,coalesce(sum(discount),0)discounts,(SELECT coalesce(sum(returned_value),0)FROM items)return_value,coalesce(sum(quantity),0)::int units_sold,count(*)::int completed_sales,(SELECT count(*)FROM items WHERE unit_cost IS NULL)::int missing_cost_items FROM invoices),
products AS(SELECT coalesce(product_id::text,'instant:'||product_name)key,product_name,max(article)article,sum(net_quantity)::int quantity,sum(net_revenue)revenue,CASE WHEN bool_or(cogs IS NULL)THEN NULL ELSE sum(cogs)END cogs,CASE WHEN bool_or(profit IS NULL)THEN NULL ELSE sum(profit)END profit FROM items GROUP BY product_id,product_name),variants AS(SELECT coalesce(variant_id::text,'instant:'||product_name)key,product_name,max(article)article,size,colour,barcode,sum(net_quantity)::int quantity,sum(net_revenue)revenue,CASE WHEN bool_or(cogs IS NULL)THEN NULL ELSE sum(cogs)END cogs,CASE WHEN bool_or(profit IS NULL)THEN NULL ELSE sum(profit)END profit FROM items GROUP BY variant_id,product_name,size,colour,barcode),categories AS(SELECT coalesce(category_id::text,'uncategorized')key,category_name name,sum(net_quantity)::int quantity,sum(net_revenue)revenue,CASE WHEN bool_or(cogs IS NULL)THEN NULL ELSE sum(cogs)END cogs,CASE WHEN bool_or(profit IS NULL)THEN NULL ELSE sum(profit)END profit FROM items GROUP BY category_id,category_name),brands AS(SELECT coalesce(brand_id::text,'unbranded')key,brand_name name,sum(net_quantity)::int quantity,sum(net_revenue)revenue,CASE WHEN bool_or(cogs IS NULL)THEN NULL ELSE sum(cogs)END cogs,CASE WHEN bool_or(profit IS NULL)THEN NULL ELSE sum(profit)END profit FROM items GROUP BY brand_id,brand_name),daily AS(SELECT sale_date::date date,count(DISTINCT sale_id)::int invoices,sum(net_quantity)::int units,sum(net_revenue)revenue,sum(discount)discount,sum(returned_value)returns,CASE WHEN bool_or(cogs IS NULL)THEN NULL ELSE sum(cogs)END cogs,CASE WHEN bool_or(profit IS NULL)THEN NULL ELSE sum(profit)END profit FROM items GROUP BY sale_date::date),paged AS(SELECT * FROM invoices ORDER BY CASE WHEN p_sort='oldest'THEN sale_date END ASC,CASE WHEN p_sort='revenue_desc'THEN net_sales END DESC,CASE WHEN p_sort='cogs_desc'THEN cogs END DESC,CASE WHEN p_sort='profit_desc'THEN profit END DESC,CASE WHEN p_sort='profit_asc'THEN profit END ASC,CASE WHEN p_sort='margin_desc'THEN margin END DESC,CASE WHEN p_sort='newest'OR p_sort IS NULL THEN sale_date END DESC,sale_id LIMIT least(greatest(p_page_size,1),100)OFFSET(greatest(p_page,1)-1)*least(greatest(p_page_size,1),100))
SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(paged))FROM paged),'[]'::jsonb),'total',(SELECT count(*)FROM invoices),'summary',to_jsonb(summary),'products',coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('margin',CASE WHEN revenue=0 OR profit IS NULL THEN 0 ELSE profit/revenue*100 END)ORDER BY profit DESC NULLS LAST)FROM products x),'[]'::jsonb),'variants',coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('margin',CASE WHEN revenue=0 OR profit IS NULL THEN 0 ELSE profit/revenue*100 END)ORDER BY profit DESC NULLS LAST)FROM variants x),'[]'::jsonb),'categories',coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('margin',CASE WHEN revenue=0 OR profit IS NULL THEN 0 ELSE profit/revenue*100 END)ORDER BY profit DESC NULLS LAST)FROM categories x),'[]'::jsonb),'brands',coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('margin',CASE WHEN revenue=0 OR profit IS NULL THEN 0 ELSE profit/revenue*100 END)ORDER BY profit DESC NULLS LAST)FROM brands x),'[]'::jsonb),'daily',coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('margin',CASE WHEN revenue=0 OR profit IS NULL THEN 0 ELSE profit/revenue*100 END)ORDER BY date)FROM daily x),'[]'::jsonb),'trend',coalesce((SELECT jsonb_agg(jsonb_build_object('date',date,'revenue',revenue,'cogs',coalesce(cogs,0),'profit',coalesce(profit,0))ORDER BY date)FROM daily),'[]'::jsonb))FROM summary;
$$;
CREATE OR REPLACE FUNCTION public.get_profit_report_items(p_filters jsonb DEFAULT '{}'::jsonb,p_sale_id uuid DEFAULT NULL)RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$SELECT coalesce(jsonb_agg(jsonb_build_object('sale_item_id',sale_item_id,'sale_id',sale_id,'invoice_number',invoice_number,'product_name',product_name,'article',article,'size',size,'colour',colour,'barcode',barcode,'quantity',quantity,'selling_price',selling_price,'discount',discount,'returned_value',returned_value,'net_revenue',net_revenue,'unit_cost',unit_cost,'total_cost',cogs,'profit',profit,'margin',margin)ORDER BY sale_date,invoice_number,product_name),'[]'::jsonb)FROM public.profit_report_item_rows(p_filters)WHERE p_sale_id IS NULL OR sale_id=p_sale_id;$$;
CREATE OR REPLACE FUNCTION public.get_profit_dashboard_summary(p_start_date date,p_end_date date)RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$WITH i AS(SELECT * FROM public.profit_report_item_rows(jsonb_build_object('startDate',p_start_date,'endDate',p_end_date)))SELECT jsonb_build_object('revenue',coalesce(sum(net_revenue),0),'cogs',CASE WHEN bool_or(cogs IS NULL)THEN NULL ELSE coalesce(sum(cogs),0)END,'profit',CASE WHEN bool_or(profit IS NULL)THEN NULL ELSE coalesce(sum(profit),0)END,'sales',count(DISTINCT sale_id))FROM i;$$;
REVOKE ALL ON FUNCTION public.profit_report_item_rows(jsonb),public.get_profit_report(jsonb,integer,integer,text),public.get_profit_report_items(jsonb,uuid),public.get_profit_dashboard_summary(date,date)FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.profit_report_item_rows(jsonb),public.get_profit_report(jsonb,integer,integer,text),public.get_profit_report_items(jsonb,uuid),public.get_profit_dashboard_summary(date,date)TO authenticated;
